fn (mut rl RateLimiter) check_and_wait(estimated_tokens int) ! {
	rl.mtx.@lock()
	defer {
		rl.mtx.unlock()
	}
	now := time.now().unix()
	if now >= rl.minute_reset_time {
		rl.requests_this_minute = 0
		rl.tokens_this_minute = 0
		rl.minute_reset_time = now + 60
	}
	if now >= rl.hour_reset_time {
		rl.requests_this_hour = 0
		rl.tokens_this_hour = 0
		rl.hour_reset_time = now + 3600
	}
	if now >= rl.day_reset_time {
		rl.requests_this_day = 0
		rl.tokens_this_day = 0
		rl.day_reset_time = now + 86400
	}
	for rl.requests_this_minute >= rl.config.req_per_min - 1 {
		wait_time := rl.minute_reset_time - time.now().unix()
		if wait_time > 0 {
			rl.mtx.unlock()
			time.sleep(wait_time * time.second)
			rl.mtx.@lock()
		}
		rl.requests_this_minute = 0
		rl.tokens_this_minute = 0
		rl.minute_reset_time = time.now().unix() + 60
	}
	for rl.tokens_this_minute + estimated_tokens > rl.config.tokens_per_min {
		wait_time := rl.minute_reset_time - time.now().unix()
		if wait_time > 0 {
			rl.mtx.unlock()
			time.sleep(wait_time * time.second)
			rl.mtx.@lock()
		}
		rl.tokens_this_minute = 0
		rl.minute_reset_time = time.now().unix() + 60
	}
	if rl.requests_this_hour >= rl.config.req_per_hour {
		return error('Hourly request limit reached for ${rl.model_name}')
	}
	if rl.requests_this_day >= rl.config.req_per_day {
		return error('Daily request limit reached for ${rl.model_name}')
	}
	rl.requests_this_minute++
	rl.requests_this_hour++
	rl.requests_this_day++
	rl.tokens_this_minute += estimated_tokens
	rl.tokens_this_hour += estimated_tokens
	rl.tokens_this_day += estimated_tokens
}

fn clean_html_tags(text string) string {
	mut result := text
	result = result.replace('<', ' <')
	result = result.replace('>', '> ')
	mut in_tag := false
	mut cleaned := strings.new_builder(result.len)
	for ch in result {
		if ch == `<` {
			in_tag = true
			continue
		}
		if ch == `>` {
			in_tag = false
			continue
		}
		if !in_tag {
			cleaned.write_u8(ch)
		}
	}
	mut final_text := cleaned.str()
	final_text = final_text.replace('&nbsp;', ' ')
	final_text = final_text.replace('&amp;', '&')
	final_text = final_text.replace('&lt;', '<')
	final_text = final_text.replace('&gt;', '>')
	final_text = final_text.replace('&quot;', '"')
	final_text = final_text.replace('&#39;', "'")
	final_text = final_text.replace('&#8217;', "'")
	final_text = final_text.replace('&#8220;', '"')
	final_text = final_text.replace('&#8221;', '"')
	final_text = final_text.replace('&#8211;', '-')
	final_text = final_text.replace('&#8212;', '-')
	final_text = final_text.replace('  ', ' ')
	final_text = final_text.replace('   ', ' ')
	final_text = final_text.replace('    ', ' ')
	return final_text.trim_space()
}

fn extract_between(text string, start_marker string, end_marker string) string {
	start_idx := text.index(start_marker) or { return '' }
	after_start := text[start_idx + start_marker.len..]
	end_idx := after_start.index(end_marker) or { return after_start }
	return after_start[..end_idx]
}

fn extract_all_between(text string, start_marker string, end_marker string) []string {
	mut results := []string{}
	mut search_text := text
	for {
		start_idx := search_text.index(start_marker) or { break }
		after_start := search_text[start_idx + start_marker.len..]
		end_idx := after_start.index(end_marker) or { break }
		results << after_start[..end_idx]
		search_text = after_start[end_idx + end_marker.len..]
	}
	return results
}

