async function scrape(url: string): Promise<string> { let resp = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36 JAIDE-Scraper/1.0', Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8' } }); if (resp.status===429) { await new Promise(r=>setTimeout(r,15000)); resp = await fetch(url); } if ([500,502,503].includes(resp.status)) { await new Promise(r=>setTimeout(r,5000)); resp = await fetch(url); } if (!resp.ok) throw new Error('http '+resp.status); return await resp.text(); }
function extract_links(html: string, base: string): string[] { const links: string[] = []; const re = /href="([^"]+)"/g; let m: RegExpExecArray | null; while ((m=re.exec(html))) { const link = m[1]; if (link.startsWith('/abs/')||link.startsWith('/pdf/')||link.startsWith('/list/')||link.startsWith('/archive/')||link.startsWith('/search/')) { const full = link.startsWith('http')?link:(base+link); if (!full.includes('.pdf') && !links.includes(full)) links.push(full); } } return links; }
