async function main() { const crawlQueue: { url: string; depth: number }[] = []; const translateQueue: { url: string; content: string; subjects: string }[] = []; const resultQueue: JAIDETrainingExample[] = []; const visited = new Set<string>(); const limiters = MODELS.map(m=>new RateLimiter(m)); const nextModel = (()=>{ let i=0; return ()=>{ const idx=i%MODELS.length; i++; return { model: MODELS[idx], limiter: limiters[idx] }; }; })(); const startUrls = [ BASE_URL, BASE_URL+'/list/cs/new', BASE_URL+'/list/cs/recent', BASE_URL+'/list/astro-ph/new', BASE_URL+'/list/cond-mat/new', BASE_URL+'/list/gr-qc/new', BASE_URL+'/list/hep-th/new', BASE_URL+'/list/math/new', BASE_URL+'/list/quant-ph/new', BASE_URL+'/archive/cs', BASE_URL+'/archive/math' ]; for (const u of startUrls) crawlQueue.push({ url: u, depth: 0 }); let pages = 0; async function crawlWorker() { while (true) { const task = crawlQueue.shift(); if (!task) { await new Promise(r=>setTimeout(r,50)); if (!crawlQueue.length) break; else continue; } if (visited.has(task.url)) continue; visited.add(task.url); try { const html = await scrape(task.url); const { content, subjects } = extract_content(html); if (content.length>=MIN_CONTENT_LEN) translateQueue.push({ url: task.url, content, subjects }); if (task.depth<MAX_DEPTH) { const links = extract_links(html, BASE_URL); for (const link of links) if (!visited.has(link)) crawlQueue.push({ url: link, depth: task.depth+1 }); } pages++; if (pages>=MAX_PAGES) break; await new Promise(r=>setTimeout(r,40)); } catch { await new Promise(r=>setTimeout(r,200)); } } }
